public without sharing class OwnedGroupWithoutReader {
 public static Map<String,Object> read(Set<Id> groupIds,Set<Id> userIds,Set<Id> roleIds) {
  List<Group> groups=Database.query('SELECT Id,Type,RelatedId,(SELECT UserOrGroupId FROM GroupMembers) FROM Group WHERE Id IN :groupIds',AccessLevel.SYSTEM_MODE);
  Integer members=0,userMembers=0;
  for(Group g:groups) for(GroupMember m:g.GroupMembers) { members++; if(m.UserOrGroupId.getSObjectType()==User.SObjectType) userMembers++; }
  Id selfId=UserInfo.getUserId();
  return new Map<String,Object>{
   'groups'=>groups.size(),'members'=>members,'directUserMembers'=>userMembers,
   'memberRows'=>Database.query('SELECT Id FROM GroupMember WHERE GroupId IN :groupIds',AccessLevel.SYSTEM_MODE).size(),
   'usersByIds'=>Database.query('SELECT Id FROM User WHERE Id IN :userIds',AccessLevel.SYSTEM_MODE).size(),
   'usersByRole'=>Database.query('SELECT Id FROM User WHERE UserRoleId IN :roleIds',AccessLevel.SYSTEM_MODE).size(),
   'self'=>Database.query('SELECT Id FROM User WHERE Id=:selfId',AccessLevel.SYSTEM_MODE).size()
  };
 }
}

