@IsTest private class OwnedGroupLookupProbe {
 @TestSetup static void seed() {
  UserRole parent=new UserRole(Name='Owned Group Parent',DeveloperName='OwnedGroupParent');insert parent;
  UserRole child=new UserRole(Name='Owned Group Child',DeveloperName='OwnedGroupChild',ParentRoleId=parent.Id);insert child;
  Group roleTree=[SELECT Id FROM Group WHERE RelatedId=:parent.Id AND Type='RoleAndSubordinatesInternal' LIMIT 1];
  Group roleLeaf=[SELECT Id FROM Group WHERE RelatedId=:child.Id AND Type='Role' LIMIT 1];
  Group primary=new Group(Name='Owned Primary Group',DeveloperName='OwnedPrimaryGroup');
  Group nested=new Group(Name='Owned Nested Group',DeveloperName='OwnedNestedGroup');insert new List<Group>{primary,nested};
  insert new List<GroupMember>{new GroupMember(GroupId=primary.Id,UserOrGroupId=UserInfo.getUserId()),new GroupMember(GroupId=primary.Id,UserOrGroupId=roleTree.Id),new GroupMember(GroupId=primary.Id,UserOrGroupId=nested.Id),new GroupMember(GroupId=nested.Id,UserOrGroupId=roleLeaf.Id)};
  User target=makeUser('role-target');target.UserRoleId=child.Id;target.LastName='OwnedRoleTarget';insert target;
 }
 private static User makeUser(String key) {
  Profile profile=[SELECT Id FROM Profile WHERE Name='Standard User' LIMIT 1];
  return new User(Username='owned-group-'+key+'-'+UserInfo.getOrganizationId()+'@example.invalid',Alias='ownusr',Email='owned@example.invalid',LastName='OwnedObserver',ProfileId=profile.Id,TimeZoneSidKey='GMT',LocaleSidKey='en_US',LanguageLocaleKey='en_US',EmailEncodingKey='UTF-8');
 }
 @IsTest static void gu01() { observe('GU01'); }
 @IsTest static void gu02() { observe('GU02'); }
 @IsTest static void gu03() { observe('GU03'); }
 @IsTest static void gu04() { observe('GU04'); }
 private static void observe(String row) {
  Set<Id> groupIds=new Map<Id,Group>([SELECT Id FROM Group WHERE DeveloperName IN ('OwnedPrimaryGroup','OwnedNestedGroup')]).keySet();
  User target=[SELECT Id,UserRoleId FROM User WHERE LastName='OwnedRoleTarget' LIMIT 1];
  Set<Id> userIds=new Set<Id>{UserInfo.getUserId(),target.Id};Set<Id> roleIds=new Set<Id>{target.UserRoleId};
  Map<String,Object> result;
  System.runAs(makeUser('observer')) {
   Test.startTest();
   if(row=='GU01') result=OwnedGroupInheritedReader.read(groupIds,userIds,roleIds);
   if(row=='GU02') result=OwnedGroupWithReader.read(groupIds,userIds,roleIds);
   if(row=='GU03') result=OwnedGroupWithoutReader.read(groupIds,userIds,roleIds);
   if(row=='GU04') {
    Id profileId=UserInfo.getProfileId();
    Profile current=[SELECT PermissionsViewAllUsers,PermissionsViewAllData FROM Profile WHERE Id=:profileId];
    result=new Map<String,Object>{'viewAllUsers'=>current.PermissionsViewAllUsers,'viewAllData'=>current.PermissionsViewAllData,
     'groupOwnerField'=>Group.SObjectType.getDescribe().fields.getMap().containsKey('OwnerId'),
     'memberOwnerField'=>GroupMember.SObjectType.getDescribe().fields.getMap().containsKey('OwnerId'),
     'userOwnerField'=>User.SObjectType.getDescribe().fields.getMap().containsKey('OwnerId')};
    try { Map<String,Object> models=new Map<String,Object>(); for(SObject item:Database.query('SELECT QualifiedApiName,InternalSharingModel FROM EntityDefinition WHERE QualifiedApiName IN (\'User\',\'Group\',\'GroupMember\')',AccessLevel.SYSTEM_MODE)) models.put((String)item.get('QualifiedApiName'),item.get('InternalSharingModel')); result.put('sharingModels',models); }
    catch(Exception e) { result.put('sharingModelError',e.getTypeName()+':'+e.getMessage()); }
   }
   Test.stopTest();
  }
  System.assert(false,'GROUP_LOOKUP|'+row+'|'+JSON.serialize(result));
 }
}
